(()=>{'use strict';const HREF='/astrologie-cariera-vocatie/';const CASE11='/studii-de-caz/acte-casa-septembrie-2004/';const PARTS=Array.from({length:8},(_,i)=>`/assets/case12-vocation-img/part-${String(i+1).padStart(2,'0')}.txt?v=20261027-case12`);let imagePromise;const loadImage=()=>imagePromise||(imagePromise=Promise.all(PARTS.map(url=>fetch(url,{cache:'force-cache'}).then(r=>{if(!r.ok)throw new Error('case12 image '+r.status);return r.text()}))).then(parts=>'data:image/webp;base64,'+parts.join('')));const install=async()=>{const section=document.getElementById('studii-de-caz-home');const track=section&&section.querySelector('.av-case-showcase-grid');if(!section||!track)return false;if(track.querySelector(`a[href="${HREF}"]`))return true;if(!track.querySelector(`a[href="${CASE11}"]`))return false;const a=document.createElement('a');a.className='av-case-showcase-card av-case-local-space av-case-vocation';a.href=HREF;a.setAttribute('aria-label','Vezi studiul de caz Vocația profesională — Astrolog');a.innerHTML=`<div class="av-case-showcase-visual av-case-local-space-visual"><img width="640" height="360" loading="lazy" decoding="async" alt="Vocația profesională — Astrolog, studiu de caz AstroVip"><span class="av-case-local-space-symbol" aria-hidden="true">♄</span><span class="av-case-local-space-index" aria-hidden="true">12</span></div><div class="av-case-showcase-copy"><p class="av-case-showcase-eyebrow">STUDIU DE CAZ 12 · VOCAȚIE</p><h3>Vocația profesională — Astrolog</h3><p class="av-case-showcase-meta">MC în Capricorn · Saturn în Leu · Casa 5</p><p class="av-case-showcase-lead">Soarele în Pești, Neptun oriental și midpointul Neptun/Pluto conturează simbolic direcția profesională astrologică.</p><span class="av-case-showcase-cta">VEZI STUDIUL →</span></div>`;track.appendChild(a);const img=a.querySelector('img');loadImage().then(src=>{img.src=src}).catch(()=>{img.remove();a.querySelector('.av-case-showcase-visual').classList.add('av-case-vocation-fallback')});section.dispatchEvent(new CustomEvent('astrovip:cases-expanded',{bubbles:true,detail:{count:track.querySelectorAll(':scope > .av-case-showcase-card').length}}));return true};const boot=()=>{let tries=0;const timer=setInterval(()=>{tries++;Promise.resolve(install()).then(done=>{if(done||tries>120)clearInterval(timer)})},100);install()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();})();